readings = [0.9, None, 0.2, 'STOP', 1.0]
accepted = []
missing_count = 0
for score in readings:
    if score == 'STOP':
        break
    if score is None:
        missing_count += 1
        continue
    if score >= 0.8:
        accepted.append(score)
print(accepted, missing_count)

